// siteinfo.js -- shared "About this site" notes modal.
//
// Content lives in data/site_info.json, which is hand-maintained. It is
// deliberately NOT data/datasets.json: that registry is regenerated by
// export_web.py on every export, so anything authored there would be
// overwritten.
//
// Keys in site_info.json are dataset ids (the manifest `name` field, e.g.
// "mtmayon"), so a viewer can look up its own dataset directly and a
// landing page can look up any card.
//
// Usage:
//   import { loadSiteInfo, openSiteInfo } from './siteinfo.js';

const DATA_URL = './data/site_info.json';

let cache = null;

// Fetched once per page load; a missing file is not fatal (the viewer
// simply hides its "About" button).
export async function loadSiteInfo() {
  if (cache) return cache;
  try {
    const res = await fetch(DATA_URL, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    cache = (data && typeof data === 'object') ? data : {};
  } catch (e) {
    console.warn('site notes unavailable:', e.message);
    cache = {};
  }
  return cache;
}

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' };
const escapeHtml = (s) => String(s).replace(/[&<>"]/g, (c) => ESCAPES[c]);

// Minimal markdown subset used by site_info.json: **bold**, *italic* and
// [^n] footnote markers. Escaping happens first, so authored text can
// never inject markup.
function renderText(s) {
  let h = escapeHtml(s);
  h = h.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  h = h.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  h = h.replace(/\[\^(\d+)\]/g, '<sup class="fn"><a href="#fn-$1" id="fnref-$1">$1</a></sup>');
  return h;
}

function renderEntry(entry) {
  const parts = [];

  if (entry.summary) {
    parts.push(`<p class="si-summary">${renderText(entry.summary)}</p>`);
  }

  if (Array.isArray(entry.facts) && entry.facts.length) {
    const rows = entry.facts.map((f) => `
      <div class="si-fact">
        <dt>${escapeHtml(f.label || '')}</dt>
        <dd>${renderText(f.value || '')}</dd>
      </div>`).join('');
    parts.push(`<dl class="si-facts">${rows}</dl>`);
  }

  if (Array.isArray(entry.refs) && entry.refs.length) {
    const items = entry.refs.map((r) => `
      <li id="fn-${escapeHtml(r.n)}">
        <a class="si-backref" href="#fnref-${escapeHtml(r.n)}">${escapeHtml(r.n)}</a>
        <span>${escapeHtml(r.label || '')}</span>
        <a class="si-reflink" href="${escapeHtml(r.url || '#')}" target="_blank"
           rel="noopener noreferrer">source</a>
      </li>`).join('');
    parts.push(`<h3 class="si-h3">References</h3><ol class="si-refs">${items}</ol>`);
  }

  return parts.join('');
}

// ---- modal -------------------------------------------------------------

// The dialog is styled from the page's own theme variables (--panel-bg,
// --panel-fg, --accent, --btn-border, --dim-fg) with dark fallbacks, so it
// matches whichever theme the viewer is running without extra per-page CSS.
const CSS = `
.si-dialog {
  --si-bg: var(--panel-bg, #141a26);
  --si-fg: var(--panel-fg, #e8ecf3);
  --si-muted: var(--dim-fg, #9aa7bd);
  --si-line: var(--btn-border, #2a3342);
  --si-accent: var(--accent, #4da3ff);
  position: fixed; inset: 0; margin: auto;
  width: min(680px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  max-height: min(88vh, 900px);
  padding: 0; border: 1px solid var(--si-line); border-radius: 12px;
  background: var(--si-bg); color: var(--si-fg);
  box-shadow: 0 14px 44px rgba(0,0,0,0.5);
  overflow: hidden; display: none;
}
.si-dialog[open] { display: flex; flex-direction: column; }
.si-dialog::backdrop { background: rgba(0,0,0,0.55); backdrop-filter: blur(2px); }
.si-head {
  display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;
  padding: 14px 16px 10px; border-bottom: 1px solid var(--si-line); flex: none;
}
.si-kicker { font-size: 11px; text-transform: uppercase; letter-spacing: .04em; color: var(--si-muted); }
.si-title { margin: 2px 0 0; font-size: 1.3rem; }
.si-close {
  flex: none; background: transparent; border: 1px solid var(--si-line);
  color: inherit; border-radius: 6px; width: 34px; height: 34px;
  font-size: 20px; line-height: 1; cursor: pointer;
}
.si-close:hover { border-color: var(--si-accent); }
.si-body { padding: 14px 16px 18px; overflow-y: auto; font-size: 14px; line-height: 1.6; }
.si-summary { margin: 0 0 4px; }
.si-summary strong { color: var(--si-fg); }
.si-dialog sup.fn a { color: var(--si-accent); text-decoration: none; font-size: 11px; padding: 0 1px; }
.si-h3 { font-size: 12px; text-transform: uppercase; letter-spacing: .04em; color: var(--si-muted); margin: 18px 0 6px; }
.si-facts {
  display: grid; margin: 12px 0 0; border: 1px solid var(--si-line);
  border-radius: 8px; overflow: hidden;
}
.si-fact { display: grid; grid-template-columns: minmax(110px, 32%) 1fr; gap: 12px; padding: 8px 12px; }
.si-fact:nth-child(odd) { background: rgba(127,127,127,0.08); }
.si-fact dt { color: var(--si-muted); font-weight: 600; }
.si-fact dd { margin: 0; }
.si-refs { margin: 0; padding-left: 20px; font-size: 13px; color: var(--si-muted); }
.si-refs li { margin-bottom: 5px; }
.si-refs a { color: var(--si-accent); }
.si-backref { text-decoration: none; margin-right: 4px; }
.si-reflink { margin-left: 6px; font-size: 12px; white-space: nowrap; }
@media (max-width: 560px) {
  .si-dialog { width: calc(100vw - 16px); max-height: 90vh; }
  .si-fact { grid-template-columns: 1fr; gap: 2px; }
}
`;

let styleEl = null;
let dialog = null;
let urlSync = false;

function injectStyles() {
  if (styleEl) return;
  styleEl = document.createElement('style');
  styleEl.id = 'siteInfoStyles';
  styleEl.textContent = CSS;
  document.head.appendChild(styleEl);
}

function ensureDialog() {
  if (dialog) return dialog;
  injectStyles();
  dialog = document.createElement('dialog');
  dialog.id = 'siteInfoDialog';
  dialog.className = 'si-dialog';
  dialog.innerHTML = `
    <div class="si-head">
      <div>
        <div class="si-kicker" data-role="kicker"></div>
        <h2 class="si-title" data-role="title"></h2>
      </div>
      <button class="si-close" type="button" aria-label="Close notes">&times;</button>
    </div>
    <div class="si-body" data-role="body"></div>`;
  document.body.appendChild(dialog);

  dialog.querySelector('.si-close').onclick = () => dialog.close();
  // Clicking the backdrop (outside the dialog box) closes it.
  dialog.addEventListener('click', (e) => {
    const r = dialog.getBoundingClientRect();
    const outside = e.clientX < r.left || e.clientX > r.right
      || e.clientY < r.top || e.clientY > r.bottom;
    if (outside) dialog.close();
  });
  // Drop the ?info=1 deep link once the notes are dismissed.
  dialog.addEventListener('close', () => {
    if (!urlSync) return;
    urlSync = false;
    const url = new URL(location.href);
    if (url.searchParams.has('info')) {
      url.searchParams.delete('info');
      history.replaceState(null, '', url);
    }
  });
  return dialog;
}

// Open the notes for one dataset id. Resolves to false when the dataset
// has no entry (caller can hide its button).
//
// opts.syncUrl keeps the address bar in step (?info=1) so the open notes
// can be shared or bookmarked.
export async function openSiteInfo(id, opts = {}) {
  const info = await loadSiteInfo();
  const entry = info[id];
  if (!entry) return false;

  const dlg = ensureDialog();
  dlg.querySelector('[data-role="title"]').textContent = entry.name || id;
  dlg.querySelector('[data-role="kicker"]').textContent =
    [entry.kind, entry.region].filter(Boolean).join(' · ');
  dlg.querySelector('[data-role="body"]').innerHTML = renderEntry(entry);
  dlg.querySelector('.si-body').scrollTop = 0;
  if (!dlg.open) dlg.showModal();

  if (opts.syncUrl) {
    urlSync = true;
    const url = new URL(location.href);
    url.searchParams.set('info', '1');
    history.replaceState(null, '', url);
  }
  return true;
}
